const fs=require('fs'),path=require('path'),assert=require('assert'),crypto=require('crypto');
const root=__dirname, source=path.join(root,'after');
const harness=fs.readFileSync(path.join(source,'tests/test_short_flow_disclosure.cjs'),'utf8');
const prefix=harness.slice(0,harness.indexOf('const notes ='));
assert(prefix.includes('function render('));
const api=new Function('require','__dirname',prefix+';return {render,text};')(require,path.join(source,'tests'));
const original=fs.readFileSync(path.join(root,'baseline-stock.html.j2'),'utf8');
const raw=fs.readFileSync(process.argv[2]);
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
assert.strictEqual(sha(raw),'1450a8574935684fc7dc22dd30443d05947583e93d49046bc44f15c20d018f30');
const actual=JSON.parse(raw), current={count:0,languages:{}};
assert.strictEqual(Object.keys(actual).length,1545);
for(const locale of ['en','zh']){
 const before={},after={};
 for(const [ticker,positioning] of Object.entries(actual)){
  const sf=positioning.short_flow;assert(sf && !sf.coverage);
  const a=api.render(original,sf,locale),b=api.render(api.text,sf,locale);
  assert.deepStrictEqual(a,b,ticker+' '+locale);
  before[ticker]=a.html;after[ticker]=b.html;current.count++;
 }
 current.languages[locale]={before_sha256:sha(JSON.stringify(before)),after_sha256:sha(JSON.stringify(after)),identical:Object.keys(after).length};
}
const fixtures=JSON.parse(fs.readFileSync(path.join(root,'fixture-positioning.json'),'utf8'));
const rendered={};
for(const [name,pos] of Object.entries(fixtures)){
 rendered[name]={positioning:pos,en:api.render(api.text,pos.short_flow,'en'),zh:api.render(api.text,pos.short_flow,'zh')};
}
const out={input_positioning_sha256:sha(raw),actual_tickers:1545,current,fixture_cases:Object.keys(fixtures).length,rendered};
fs.writeFileSync(path.join(root,'consumer-proof.json'),JSON.stringify(out,null,2)+'\n');
console.log(JSON.stringify({actual_tickers:1545,current,fixture_cases:out.fixture_cases,proof_sha256:sha(fs.readFileSync(path.join(root,'consumer-proof.json')))}));
